// n8n Code node — Mode: "Run Once for All Items"
// Paste this whole block into the Code node's editor.
//
// Expects each input item to carry the raw log line in a field.
// Adjust `LOG_FIELD` below to match your actual field name
// (e.g. "line", "message", "log", "raw").
const LOG_FIELD = "line";

const CRITICAL_PATTERNS = [
  /i\/o error/i,
  /ext4-fs (error|warning)/i,
  /xfs\s*\(.+\)\s*:\s*.*error/i,
  /cpu\s+\d+:\s*cpu stopped/i,
  /kernel panic/i,
  /out of memory|oom-killer/i,
  /segfault/i,
  /read-only file system/i,
  /disk failure|hard(ware)? failure/i,
  /mount(ing)? failed|failed to mount/i,
];

const NORMAL_OVERRIDE_PATTERNS = [
  /scsi.*result:\s*0x00/i,
  /mount process started/i,
];

function classifyLogLine(line) {
  for (const pattern of NORMAL_OVERRIDE_PATTERNS) {
    if (pattern.test(line)) return "Normal";
  }
  for (const pattern of CRITICAL_PATTERNS) {
    if (pattern.test(line)) return "Critical";
  }
  return "Normal";
}

// $input.all() gives you every incoming item from the previous node.
const inputItems = $input.all();

const classified = inputItems.map((item) => {
  const line = item.json[LOG_FIELD] ?? JSON.stringify(item.json);
  return {
    json: {
      ...item.json,
      status: classifyLogLine(String(line)),
    },
  };
});

const overallStatus = classified.some((i) => i.json.status === "Critical")
  ? "Critical"
  : "Normal";

// Attach overallStatus to every item so downstream nodes (e.g. the
// HTML email node) can reference it without a separate merge step.
// If you'd rather have ONE summary item instead of per-line items,
// swap the `return classified...` line below for:
//   return [{ json: { overallStatus, results: classified.map(i => i.json) } }];
return classified.map((item) => ({
  json: { ...item.json, overallStatus },
}));

// ============================================================
// ANALYZE CRITICAL LOGS - n8n Code Node (SIMPLIFIED v3)
// Output: ONLY status + per-line log details (with conclusion
// and solution) + one overall conclusion/solution.
// No critical/high/medium/total_findings/total_log_lines counts.
// ============================================================
//
// Mode: "Run Once for All Items"
// Auto-detects input shape (multiple items, one blob with
// multiple lines, or an array field) - same detection as before.
// ============================================================

const LOG_FIELD_CANDIDATES = ['line', 'message', 'log', 'raw', 'text', 'data'];

// ---- Step 1: extract raw chunks from whatever shape the input is ----
const inputItems = $input.all();
const rawChunks = [];

for (const item of inputItems) {
  const j = item.json;

  if (typeof j === 'string') {
    rawChunks.push(j);
    continue;
  }

  let matchedField = null;
  for (const field of LOG_FIELD_CANDIDATES) {
    if (j[field] !== undefined && j[field] !== null) {
      matchedField = field;
      break;
    }
  }

  if (matchedField) {
    const value = j[matchedField];
    if (Array.isArray(value)) {
      rawChunks.push(...value.map(String));
    } else {
      rawChunks.push(String(value));
    }
  } else {
    rawChunks.push(JSON.stringify(j));
  }
}

// ---- Step 2: split multi-line blobs into individual lines ----
const lines = rawChunks
  .flatMap((chunk) => chunk.split(/\r?\n/))
  .map((l) => l.trim())
  .filter((l) => l.length > 0);

// ============================================================
// KNOWLEDGE BASE: pattern -> severity + conclusion + solution
// Checked in order; first match wins for a given line.
// ============================================================

const RULES = [
  {
    pattern: /scsi.*result:\s*0x00/i,
    severity: 'normal',
    conclusion: 'SCSI command completed successfully.',
    solution: 'No action needed.',
  },
  {
    pattern: /mount process started/i,
    severity: 'normal',
    conclusion: 'Routine mount operation starting.',
    solution: 'No action needed.',
  },
  {
    pattern: /cdb:\s*read\(10\)/i,
    severity: 'normal',
    conclusion: 'Routine disk read command, no error reported.',
    solution: 'No action needed.',
  },
  {
    pattern: /unmount initiated while filesystem is being checked|umount failed/i,
    severity: 'critical',
    conclusion: 'Filesystem was unmounted or unmount failed while an fsck/check was in progress, risking metadata corruption.',
    solution: 'Do not remount until a full fsck completes cleanly. Take the volume offline, run fsck to completion, then verify data integrity from backup before returning to service.',
  },
  {
    pattern: /error starting i\/o/i,
    severity: 'critical',
    conclusion: 'The filesystem failed to even initiate an I/O request to the underlying block device, indicating the device or controller path is unresponsive.',
    solution: 'Check dmesg/SMART data for the underlying disk immediately, verify cabling/backplane and controller health, and fail over to a redundant path or replace the disk if SMART shows pending sectors.',
  },
  {
    pattern: /i\/o error/i,
    severity: 'critical',
    conclusion: 'A read/write I/O error occurred against the underlying block device.',
    solution: 'Run smartctl on the affected disk, check for bad sectors, review RAID/controller logs, and restore affected files from backup if corruption is confirmed.',
  },
  {
    pattern: /ext4-fs (error|warning)/i,
    severity: 'critical',
    conclusion: 'EXT4 filesystem reported an internal error/warning, often triggered by an underlying disk I/O problem.',
    solution: 'Schedule a fsck on next reboot (or take the volume offline now), inspect the disk for hardware faults, and validate backups are current before remediation.',
  },
  {
    pattern: /inline extent failed to allocate block|inline_data.*failed/i,
    severity: 'critical',
    conclusion: 'EXT4 could not allocate a block for inline data, usually caused by filesystem corruption or the volume running out of free space/inodes.',
    solution: 'Check free space and inode usage (df -i), run fsck offline, and if corruption persists, restore the affected filesystem from backup.',
  },
  {
    pattern: /xfs\s*\(.+\)\s*:.*error/i,
    severity: 'critical',
    conclusion: 'XFS filesystem reported an error, typically from a failing disk or corrupted metadata.',
    solution: 'Run xfs_repair in dry-run mode first (xfs_repair -n) to assess damage, check underlying disk health, and restore from backup if repair reports unrecoverable corruption.',
  },
  {
    pattern: /cpu\s+\d+:\s*cpu stopped/i,
    severity: 'critical',
    conclusion: 'A CPU core halted (TIF_HALT), which can indicate a kernel panic, thermal shutdown, or hardware fault on that core.',
    solution: 'Check full dmesg/kernel panic trace around this timestamp, review system temperature and power logs, and run hardware diagnostics on the CPU/motherboard.',
  },
  {
    pattern: /kernel panic/i,
    severity: 'critical',
    conclusion: 'The kernel panicked and the system likely crashed or rebooted.',
    solution: 'Collect the full panic trace (netconsole/kdump if configured), identify the triggering subsystem, and check for recent driver/kernel updates or failing hardware.',
  },
  {
    pattern: /out of memory|oom-killer/i,
    severity: 'critical',
    conclusion: 'The OOM killer terminated a process due to memory exhaustion.',
    solution: 'Identify the process that was killed, check for memory leaks, review swap/memory sizing, and consider adding memory or setting cgroup limits.',
  },
  {
    pattern: /segfault/i,
    severity: 'critical',
    conclusion: 'A process crashed with a segmentation fault.',
    solution: 'Identify the crashing binary and check application/system logs for a core dump; update or patch the software if this is a known bug.',
  },
  {
    pattern: /read-only file system/i,
    severity: 'critical',
    conclusion: 'The filesystem was remounted read-only, usually as a kernel protective response to a detected I/O error.',
    solution: 'Investigate the underlying disk immediately (this is a protective fallback, not the root cause), then fsck and remount read-write once the disk is confirmed healthy.',
  },
  {
    pattern: /disk failure|hard(ware)? failure/i,
    severity: 'critical',
    conclusion: 'A hardware failure was reported on a storage device.',
    solution: 'Treat as an active hardware incident - fail over to redundant storage if available and schedule immediate disk replacement.',
  },
  {
    pattern: /host-adapter reported error/i,
    severity: 'high',
    conclusion: 'The SCSI/SAS/SATA host adapter reported an error communicating with the device, pointing to a controller, cable, or adapter-level fault rather than the disk media itself.',
    solution: 'Reseat/replace cabling, check the HBA/controller firmware and logs, and test the disk on a different port or controller to isolate adapter vs. disk fault.',
  },
  {
    pattern: /scsi error 0x[0-9a-f]+/i,
    severity: 'high',
    conclusion: 'A SCSI command returned a non-zero error code.',
    solution: 'Decode the SCSI sense/error code, check disk and controller health, and monitor for recurrence - repeated errors on the same device indicate imminent failure.',
  },
  {
    pattern: /scsi.*result:\s*0x(?!00)[0-9a-f]+/i,
    severity: 'high',
    conclusion: 'A SCSI command completed with a non-success result code.',
    solution: 'Review the specific result/sense code, check disk SMART status, and escalate to hardware replacement if the code indicates a media or mechanical fault.',
  },
  {
    pattern: /controller error/i,
    severity: 'high',
    conclusion: 'The storage controller reported an internal error.',
    solution: 'Check controller firmware version and logs, and consider a firmware update or controller replacement if errors recur.',
  },
  {
    pattern: /link reset/i,
    severity: 'high',
    conclusion: 'A storage link (SAS/FC) was reset, indicating an unstable physical connection.',
    solution: 'Inspect cabling, transceivers, and switch/HBA ports; replace suspect hardware if resets continue.',
  },
  {
    pattern: /timeout/i,
    severity: 'high',
    conclusion: 'An operation timed out, suggesting a slow or unresponsive device/service.',
    solution: 'Check device/service load and latency, review timeout thresholds, and investigate the specific component that failed to respond in time.',
  },
  {
    pattern: /retry/i,
    severity: 'medium',
    conclusion: 'An operation was retried after an initial failure, a warning sign of an intermittent issue.',
    solution: 'Monitor for a pattern - occasional retries can be benign, but a rising frequency indicates a developing hardware or network problem worth investigating now.',
  },
  {
    pattern: /degraded/i,
    severity: 'medium',
    conclusion: 'A resource (RAID array, service, or link) is running in a degraded state.',
    solution: 'Identify which component is degraded and restore redundancy (e.g. rebuild RAID, replace failed member) before a second fault causes an outage.',
  },
  {
    pattern: /mount(ing)? failed|failed to mount/i,
    severity: 'medium',
    conclusion: 'A mount operation failed, possibly due to configuration or a busy/unavailable device.',
    solution: 'Check the exact mount error, verify the device/network share is available, and confirm fstab/systemd mount unit configuration is correct.',
  },
];

function analyzeLine(line) {
  for (const rule of RULES) {
    if (rule.pattern.test(line)) {
      return { line, severity: rule.severity, conclusion: rule.conclusion, solution: rule.solution };
    }
  }
  return {
    line,
    severity: 'normal',
    conclusion: 'No known issue pattern matched.',
    solution: 'No action needed.',
  };
}

// ---- Step 3: analyze every line ----
const logs = lines.map(analyzeLine);

// ---- Step 4: overall status (worst severity wins) ----
const hasCritical = logs.some((l) => l.severity === 'critical');
const hasHigh = logs.some((l) => l.severity === 'high');
const hasMedium = logs.some((l) => l.severity === 'medium');

let status = 'HEALTHY';
if (hasCritical || hasHigh) status = 'CRITICAL';
else if (hasMedium) status = 'WARNING';

// ---- Step 5: overall conclusion + solution, built from the actual findings ----
const issueLogs = logs.filter((l) => l.severity !== 'normal');

let overall_conclusion;
let overall_solution;

if (issueLogs.length === 0) {
  overall_conclusion = 'All log lines are routine; no critical, high, or warning-level issues were detected.';
  overall_solution = 'No action required. Continue normal monitoring.';
} else {
  const uniqueConclusions = [...new Set(issueLogs.map((l) => l.conclusion))];
  const uniqueSolutions = [...new Set(issueLogs.map((l) => l.solution))];

  overall_conclusion =
    `${issueLogs.length} of ${logs.length} log line(s) indicate problems. ` +
    uniqueConclusions.join(' ');

  overall_solution =
    'Recommended actions, in priority order: ' +
    uniqueSolutions.map((s, i) => `${i + 1}) ${s}`).join(' ');
}

// ============================================================
// OUTPUT - status, logs (with per-line conclusion/solution),
// and one overall conclusion/solution
// ============================================================

return [
  {
    json: {
      status,
      logs,
      overall_conclusion,
      overall_solution,
    },
  },
];

